#!/usr/bin/python3
# build_catalog.py — source of truth for the Blaque Baux BLOCK derivatives catalog. Encodes the 120 strategy
# building blocks from the Derivatives Master Reference (Kareem Williams / Carter Warrens), emits the
# machine-readable catalog (derivatives_catalog.json), the JSON schema (schema.json), and a human index
# (INDEX.md). No pricing code — this is the taxonomy/backbone the rest of Block hangs off. Run: python build_catalog.py
import json, os, datetime
HERE = os.path.dirname(os.path.abspath(__file__))

# ---- entry helper: keep the source compact but the JSON complete ----
# S(id, name, tag, family, parties, legs, params, settlement, payoff, variants, combos, use, slide, detail="diagram")
def S(id, name, tag, family, parties, legs, params, settlement, payoff, variants, combos, use, slide, detail="diagram"):
    return dict(id=id, name=name, tag=tag, family=family, parties=parties, legs=legs, parameters=params,
                settlement=settlement, payoff=payoff, variants=variants, combinations=combos, use=use,
                deck_slide=slide, detail_level=detail, status="reference")

