asset_classes = {
 "rates": "Interest-rate & cross-currency derivatives",
 "fx": "Foreign-exchange derivatives (deliverable, onshore, and non-deliverable)",
 "equity": "Equity derivatives (forwards, structured notes, options, variance/vol)",
 "credit": "Credit derivatives (CDS, index, options, TRS)",
 "commodity": "Commodity derivatives",
 "municipal": "Municipal / MMD derivatives",
 "funding": "Funding, deposit & cost-of-funds instruments",
}
# blocks that now have reference pricing code (pricing/block_pricing.jl, proven in pricing_selftest.jl)
IMPLEMENTED = {"irs_vanilla", "fx_outright_forward", "fx_vanilla", "cds_single"}
all_entries = []
for ac in asset_classes:
    for e in CATALOG.get(ac, []):
        e["asset_class"] = ac                        # stamp each entry so the JSON is self-describing
        e["id"] in IMPLEMENTED and e.__setitem__("status", "implemented")
        if e["id"] == "collar":                      # first combination play tested (research/collar_overlay.jl)
            e["combination_research"] = "collar_overlay.jl — guardrail: SPY Sharpe 1.01->1.39, tail -18% vs -24%, at the cost of upside"
        all_entries.append(e)
doc = {
 "_meta": {
   "title": "Blaque Baux — Block Derivatives Catalog",
   "source": "Derivatives Master Reference (Kareem Williams / Carter Warrens, Blaque Baux initiative)",
   "generated": datetime.date.today().isoformat(),
   "count": len(all_entries),
   "status": "reference taxonomy — no pricing code yet; the backbone Block hangs off",
   "note": "Each entry is a BUILDING BLOCK, not a standalone strategy. Value is in composition "
           "(hedging / arbitrage / combination) and in the engine's governance — none is alpha alone.",
 },
 "asset_classes": asset_classes,
 "strategies": all_entries,
}
with open(os.path.join(HERE, "derivatives_catalog.json"), "w") as f:
    json.dump(doc, f, indent=2)

schema = {
 "$schema": "http://json-schema.org/draft-07/schema#",
 "title": "Blaque Baux Block strategy building-block",
 "type": "object",
 "required": ["id","name","tag","asset_class","family","parties","legs","parameters","payoff","status"],
 "properties": {
   "id": {"type":"string","description":"stable snake_case key"},
   "name": {"type":"string"}, "tag": {"type":"string","description":"deck abbreviation"},
   "asset_class": {"enum": list(asset_classes.keys())},
   "family": {"type":"string","description":"swap|forward|option|variance|barrier|swaption|..."},
   "parties": {"type":"array","items":{"type":"string"}},
   "legs": {"type":"array","description":"cash-flow legs [from,to,flow]","items":{"type":"array"}},
   "parameters": {"type":"array","items":{"type":"string"}},
   "settlement": {"type":"string"}, "payoff": {"type":"string"},
   "variants": {"type":"array","items":{"type":"string"}},
   "combinations": {"type":"array","items":{"type":"string"},"description":"documented hedging/arb/combination plays"},
   "use": {"type":"string"}, "deck_slide": {"type":"integer"},
   "detail_level": {"enum":["full","diagram"]},
   "status": {"enum":["reference","spec","implemented","validated"]},
 },
}
with open(os.path.join(HERE, "schema.json"), "w") as f:
    json.dump(schema, f, indent=2)

# markdown index
lines = ["# Block Derivatives Catalog — Index",
 "", f"*Generated from `build_catalog.py` — {doc['_meta']['count']} strategy building blocks. "
 "Machine-readable source: [`derivatives_catalog.json`](derivatives_catalog.json), schema: "
 "[`schema.json`](schema.json).*", "",
 "> Each entry is a **building block, not a standalone strategy**. None is alpha alone — the value is in "
 "**composition** (hedging / arbitrage / combination) under the engine's governance.", ""]
for ac, desc in asset_classes.items():
    ents = CATALOG.get(ac, [])
    lines += [f"## {ac.title()} — {desc}  ({len(ents)})", "",
              "| id | strategy | tag | family | key legs |", "|---|---|---|---|---|"]
    for e in ents:
        legs = " ; ".join(f"{l[0]}→{l[1]}: {l[2]}" if len(l)==3 else " ".join(l) for l in e["legs"])
        lines.append(f"| `{e['id']}` | {e['name']} | {e['tag']} | {e['family']} | {legs[:90]} |")
    lines.append("")
with open(os.path.join(HERE, "INDEX.md"), "w") as f:
    f.write("\n".join(lines))

print(f"catalog: {doc['_meta']['count']} strategies")
for ac in asset_classes: print(f"  {ac:10s} {len(CATALOG.get(ac,[]))}")
